    public static IReadOnlyList<SwShFpsMainPatcher.MainPatch> ForGame(ProjectGame game) =>
        game == ProjectGame.Sword ? Sword : Shield;

    public static IEnumerable<SwShExeFsReservedRegion> CreateReservations()
    {
        foreach (var game in new[] { ProjectGame.Sword, ProjectGame.Shield })
        {
            foreach (var patch in ForGame(game))
            {
                yield return new(SwShExeFsReservedRegionLedger.OwnerFpsPatch,
                    $"60fps-{game.ToString().ToLowerInvariant()}-clock-{patch.Offset:X}",
                    SwShExeFsReservedRegionLedger.ExeFsMainPath, "main.text",
                    patch.Offset, patch.Expected.Length, patch.Label, "do-not-overwrite");
            }
        }
    }
}
